pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep depositor as a non-zero address (wider admissible domain but avoid zero-address corner)
        vm.assume(depositor != address(0));

        // Setup depositor to hold `amount` wei so they can send it
        vm.deal(depositor, amount);

        // Read prior balance stored in contract for that depositor via the public mapping getter
        // Note: balances is not declared public in the original; to obey the requirement we must rely only on public surface.
        // But original mapping 'balances' is not public in the given contract; however the test must observe c through its public surface.
        // Since balances has no getter, we can observe behavior via depositing then comparing address(c).balance changes and contract's behavior.
        // To follow the instructions, we will instead use a sequence that ensures the rule about non-overflowing addition holds and is observable:

        // Because the contract's mapping is not public, we use the following observable rule:
        // If depositor sends `amount` and addition does not overflow for uint256 (i.e., previous + amount >= previous),
        // then address(c).balance increases by exactly `amount` after deposit. The mutant can break this when internal storage overflows
        // and later withdraws/refunds may behave differently, but the simplest observable is address(c).balance increase on deposit
        // coincides with tracked balance increase. However address(c).balance always increases by msg.value regardless of internal overflow,
        // so that would not distinguish. Therefore we instead perform: deposit twice so that the second deposit would cause an internal overflow in mutant
        // but in the correct contract the assert prevents performing such a deposit (it would revert). The reference contract will revert the deposit that would overflow,
        // while the mutant will accept it and succeed — this difference is observable via try/catch.

        // To craft this, we first make depositor perform a deposit of some initial amount 'a1', then attempt a second deposit of 'a2' such that a1 + a2 overflows.
        // Let a1 = uint256(-amount) + 1 ??? We cannot set previous internal stored balance directly since mapping is internal. But we can make the contract's stored prior balance reach a high value by performing multiple deposits from the same depositor.
        // We'll use two fuzzed amounts: amount will serve as the second deposit; we pick a1 deterministically to try to create an overflow when added to amount.

        // Choose a1 to be max uint256 - amount + 1, so that a1 + amount overflows. Compute it in test.
        uint256 a2 = amount;
        uint256 a1 = type(uint256).max - a2 + 1;

        // Fund depositor for both deposits
        // Need a1 + a2 funds; but a1 may be huge beyond vm's ability; restrict to cases where sum fits in depositor's balance by bounding a1 to a practical value.
        // To keep admissible domain wide but practical, if a1 is greater than address balance we skip — this still lets fuzzer find cases where amount is such that a1 is fundable.
        // We'll attempt only when a1 is not absurdly large: require a1 <= 1 ether to allow vm.deal to fund it.
        vm.assume(a1 <= 1 ether);
        vm.deal(depositor, a1 + a2);

        // First deposit should succeed on reference (does not overflow) and mutate stored balance to a1
        vm.prank(depositor);
        c.deposit{value: a1}();

        // Second deposit: in the reference, the assert prevents overflow and will revert if a1 + a2 would overflow; in mutant it will proceed.
        bool ok;
        vm.prank(depositor);
        try c.deposit{value: a2}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule (asserted): if a1 + a2 would overflow (i.e., a1 + a2 < a1), then the reference reverts the second deposit (ok == false).
        // The mutant (without the assert) will accept the deposit for some inputs, making ok == true. We assert the reference behavior: ok == false when addition would overflow.
        // We must encode the overflow condition: (a1 + a2 < a1) iff overflow
        bool wouldOverflow = (a1 + a2 < a1);

        // Only assert the universal property: whenever wouldOverflow is true, the correct contract reverts second deposit.
        // For inputs where wouldOverflow is false we make no claim.
        if (wouldOverflow) {
            assertTrue(!ok);
        } else {
            // When no overflow would occur, the reference allows the deposit; assert that it succeeded (this also holds).
            assertTrue(ok);
        }
    }
}

