pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an address actor and an uint256 amount to deposit.
    // We assert that deposit() never reverts on the reference for any admissible inputs.
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep the actor as a valid non-zero address to avoid degenerate EOA=address(0) edgecases
        vm.assume(actor != address(0));
        // Provide the actor with the funds to send
        vm.deal(actor, amount);

        // Try the deposit call and record whether it succeeded (no revert) or failed.
        bool ok;
        vm.prank(actor);
        try c.deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C never reverts on deposit for any sender/value (it uses assert but in Solidity 0.8 assert only triggers on overflow which the assert prevented);
        // therefore for all admissible inputs the call must succeed. The mutant removing the assert can cause behavior that leads to a failing call for some inputs,
        // so this single assertion is satisfied by the reference for all inputs and broken by the mutant for some inputs.
        assertTrue(ok);
    }
}

