pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: depositor address and amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // admissible domain: depositor must be non-zero to be meaningful
        vm.assume(depositor != address(0));

        // Ensure depositor has Ether to send
        uint256 sendAmount = bound(amount, 0, type(uint256).max);
        vm.deal(depositor, sendAmount);

        // read prior balance via the contract's public mapping getter: balances is not public in C,
        // so we cannot call c.balances(depositor). Instead, we observe by performing a deposit of 0
        // to learn the stored balance: first, if contract allows deposit(0), it will not change balance
        // but we need to read balances — because mapping is private, we instead infer by performing
        // a safe small deposit to check strict increase under the stated precondition (prior < max).

        // To establish the precondition, if prior is max we cannot rely on reading it directly.
        // Workaround: first deposit 0 to ensure call succeeds and then deposit a tiny amount to test.
        // But deposit(0) is allowed and should not change the stored value in reference.

        // We'll proceed: if prior == max, then the precondition fails; we must assume prior < max.
        // We cannot read prior directly, so to ensure prior < max, we perform a zero-value call first
        // and then perform the actual deposit under the assumption that before the deposit the stored
        // balance is not max. We conservatively assume the contract's stored balance for depositor is < max,
        // by disallowing the case where depositor previously reached max via an initial large funded deposit.

        // To ensure the depositor's prior stored balance is < max, reset environment by creating a fresh
        // depositor state: call deposit with 0 from depositor to have no-op, then perform the actual deposit.
        // Note: cannot reset mapping, but since c was freshly deployed and no deposits yet, prior is 0 (< max).

        // confirm start state: contract freshly deployed so prior balances are zero
        // perform the fuzzed deposit
        vm.prank(depositor);
        c.deposit{value: sendAmount}();

        // After deposit, the contract's recorded balance for depositor should be > 0 (since prior 0 < max)
        // We assert that address(c).balance increased by at least 0 and that depositor's recorded balance > 0
        // But mapping is not public, so we cannot read it; instead, we check that sending a further deposit of 1
        // increases address(c).balance and that the contract will accept another deposit call successfully.

        // The key observable: for a fresh contract (prior balance 0 < max), making a nonzero deposit must
        // result in address(c).balance > 0 and any subsequent deposit must succeed. We assert that if prior < max
        // (which holds because c is fresh and prior == 0) then after deposit the contract's balance is >= sendAmount

        // Exactly one assertion observing c: after deposit from fresh state, address(c).balance >= sendAmount
        assertTrue(address(c).balance >= sendAmount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: deposits value and checks contract balance increased by that value
    function runTest(uint256 amount) public payable {
        // require the tester sent enough ETH to this contract to forward
        require(address(this).balance >= amount);
        // record prior contract balance
        uint256 before = address(c).balance;
        // perform deposit on C forwarding `amount` wei
        c.deposit{value: amount}();
        // observe after balance
        uint256 after = address(c).balance;
        // The original contract increments balances[msg.sender] before forwarding funds out, so
        // after deposit the contract's balance must have increased by exactly amount.
        // The mutant reorders the assert and can allow a subsequent overflow/misaccount causing mismatch.
        assert(after == before + amount);
    }

    // Allow this helper contract to receive ETH so it can forward deposits
    receive() external payable {}
}

