        c.deposit{value: amount}();

        // Now attempt to withdraw the same amount; record whether withdraw reverted
        bool withdrew;
        try c.withdraw(amount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // The invariant: after a deposit of amount > 0 from this caller, withdraw(amount) should succeed.
